// >>> rolling_max([1, 2, 3, 2, 3, 4, 2])
// [1, 2, 3, 3, 3, 4, 4]
function rolling_max(numbers){
    var result = [];
    var max = -Infinity;
    for (var i = 0; i < numbers.length; i++){
        max = Math.max(max, numbers[i]);
        result.push(max);
    }
    return result;
}
