// [1, 3, 4]
function remove_duplicates(numbers){
    var result = [];
    var seen = {};
    for(var i = 0; i < numbers.length; i++){
        var n = numbers[i];
        if(seen[n]){
            continue;
        }
        seen[n] = true;
