    var i = 0;
    var j = 0;
    var k = 0;
    var l = 0;
    var sum = 0;
    var result = false;
    for (i = 0; i <= n; i += 2) {
        for (j = 0; j <= n; j += 2) {
            for (k = 0; k <= n; k += 2) {
                for (l = 0; l <= n; l += 2) {
                    sum = i + j + k + l;
                    if (sum == n) {
                        result = true;
                    }
                }
            }
        }
    }
    return result;
}
