// For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
// Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
// and a[i] + a[j] + a[k] is a multiple of 3.
// Example :
// >>> get_max_triples(5)
// 1
// Explanation: 
// a = [1, 3, 7, 13, 21]
// The only valid triple is (1, 7, 13).
function get_max_triples(n){
    var a = [];
    for(var i=0;i<n;i++){
        a[i] = i*i-i+1;
    }
    var count = 0;
    for(var i=0;i<n;i++){
        for(var j=i+1;j<n;j++){
            for(var k=j+1;k<n;k++){
                if((a[i]+a[j]+a[k])%3==0){
                    count++;
                }
            }
        }
    }
    return count;
}
//You are given a positive integer n. You have to create an integer array a of length n.
// For each i (1 ≤ i ≤ n), the value of a[i] = i * i - i + 1.
// Return the number of triples (a[i], a[j], a[k]) of a where i < j < k, 
// and a[i] + a[j] + a[k] is a multiple of 3.
// Example :
// >>> get_max_triples(5)
// 1
// Explanation: 
// a = [1, 3, 7, 13, 21]
// The only valid triple is (1, 7, 13).
function get_max_triples(n){
    // your code
    let a = [];
    for(let i = 1; i <= n; i++){
        a.push(i*i - i + 1);
    }
    let count = 0;
    for(let i = 0; i < n; i++){
        for(let j = i + 1; j < n; j++){
            for(let k = j + 1; k < n; k++){
                if((a[i] + a[j] + a[k]) % 3 === 0){
                    count++;
                }
            }
        }
    }
    return count;
}

module.exports = get_max_triples;
