// >>> compare([0, 5, 0, 0, 0, 4], [4, 1, 1, 0, 0, -2])
// [4, 4, 1, 0, 0, 6]
function compare(game, guess){
  var result = [];
  for(var i=0; i<game.length; i++){
    if(game[i] === guess[i]){
      result.push(0);
    } else {
      result.push(Math.abs(game[i] - guess[i])
    }
  }
  return result;
}
