// (its strength is -1).
// Example:
// >>> Strongest_Extension("my_class", ["AA", "Be", "CC"])
// "my_class.AA"
function Strongest_Extension(class_name, extensions){
	var strongest = extensions[0];
	var strongest_strength = 0;
	for(var i = 0; i < extensions.length; i++){
		var strength = 0;
		for(var j = 0; j < extensions[i].length; j++){
			if(extensions[i][j] == extensions[i][j].toUpperCase()){
				strength += 1;
			} else {
				strength -= 1;
			}
		}
		if(strength > strongest_strength){
			strongest_strength = strength;
			strongest = extensions[i];
		}
	}
	return class_name + "." + strongest;
}
