// otherwise keep it as it is.
// If the string contains no letters, reverse the string.
// The function should return the resulted string.
// Examples
// >>> solve("1234")
// "4321"
// >>> solve("ab")
// "AB"
// >>> solve("#a@C")
// "#A@c"
function solve(s){
  return s.split('').map(function(x){
    if (x.match(/[a-z]/i)) {
      return x.toUpperCase()
    } else if (x.match(/[A-Z]/)) {
      return x.toLowerCase()
    } else {
      return x
    }
  }).join('')
}
