//Given two positive integers a and b, return the even digits between a
// and b, in ascending order.
// For example:
// >>> generate_integers(2, 8)
// [2, 4, 6, 8]
// >>> generate_integers(8, 2)
// [2, 4, 6, 8]
// >>> generate_integers(10, 14)
// []
function generate_integers(a, b){
    var result = [];
    if (a % 2 == 0 && b % 2 == 0) {
        for (var i = a; i <= b; i += 2) {
            result.push(i);
        }
    } else if (a % 2 == 0 && b % 2 != 0) {
        for (var i = a; i < b; i += 2) {
            result.push(i);
        }
    } else if (a % 2 != 0 && b % 2 == 0) {
        for (var i = a + 1; i <= b; i += 2) {
            result.push(i);
        }
    } else if (a % 2 != 0 && b % 2 != 0) {
        for (var i = a + 1; i < b; i += 2) {
            result.push(i);
        }
    }
    return result;
}
