// [2, 4, 6, 8]
// >>> generate_integers(8, 2)
// [2, 4, 6, 8]
// >>> generate_integers(10, 14)
// []
function generate_integers(a, b){
    var result = [];
    var start = Math.min(a, b);
    var end = Math.max(a, b);
    for (var i = start; i <= end; i++) {
        if (i % 2 == 0) {
            result.push(i);
        }
    }
    return result;
}
